// Puts "Translate+" in Android's text-selection menu (PROCESS_TEXT) and Share sheet (SEND).
// The android/ folder is generated by `expo prebuild`, so this is done as a config plugin:
// it survives every rebuild, locally and on GitHub Actions.
//
// The incoming text is turned into a translateplus://translate?text=… link before React
// Native sees the intent, so the app reads it with the ordinary Linking API.
const { withAndroidManifest, withMainActivity } = require('expo/config-plugins');

const FILTERS = [
  { action: 'android.intent.action.PROCESS_TEXT', mime: 'text/plain' },
  { action: 'android.intent.action.SEND', mime: 'text/plain' },
];

function withShareManifest(config) {
  return withAndroidManifest(config, (cfg) => {
    const app = cfg.modResults.manifest.application?.[0];
    const main = app?.activity?.find((a) => a.$['android:name'] === '.MainActivity');
    if (!main) throw new Error('with-share-text: MainActivity not found in AndroidManifest.xml');
    main['intent-filter'] = main['intent-filter'] || [];
    for (const f of FILTERS) {
      const exists = main['intent-filter'].some((filter) =>
        (filter.action || []).some((a) => a.$['android:name'] === f.action)
      );
      if (exists) continue;
      main['intent-filter'].push({
        action: [{ $: { 'android:name': f.action } }],
        category: [{ $: { 'android:name': 'android.intent.category.DEFAULT' } }],
        data: [{ $: { 'android:mimeType': f.mime } }],
      });
    }
    return cfg;
  });
}

const MARKER = '// translate-plus: shared text';

const HELPER = `
  ${MARKER}
  override fun onNewIntent(intent: Intent) {
    val link = asTranslateLink(intent)
    setIntent(link)
    super.onNewIntent(link)
  }

  /** Text selected or shared from another app becomes a translateplus://translate link. */
  private fun asTranslateLink(intent: Intent): Intent {
    val text = when (intent.action) {
      Intent.ACTION_PROCESS_TEXT -> intent.getCharSequenceExtra(Intent.EXTRA_PROCESS_TEXT)?.toString()
      Intent.ACTION_SEND -> if (intent.type == "text/plain") intent.getStringExtra(Intent.EXTRA_TEXT) else null
      else -> null
    }
    if (text.isNullOrBlank()) return intent
    return Intent(Intent.ACTION_VIEW, Uri.parse("translateplus://translate?text=" + Uri.encode(text.take(5000))))
  }
`;

function withShareActivity(config) {
  return withMainActivity(config, (cfg) => {
    if (cfg.modResults.language !== 'kt') throw new Error('with-share-text: expected a Kotlin MainActivity');
    let src = cfg.modResults.contents;
    if (src.includes(MARKER)) return cfg;
    for (const imp of ['android.content.Intent', 'android.net.Uri']) {
      if (!src.includes(`import ${imp}\n`)) src = src.replace(/^(package .+\n)/m, `$1\nimport ${imp}`);
    }
    // the launch intent is converted before React Native reads it
    const created = /super\.onCreate\((null|savedInstanceState)\)/;
    if (!created.test(src)) throw new Error('with-share-text: onCreate not found in MainActivity');
    src = src.replace(created, (m) => `setIntent(asTranslateLink(intent))\n    ${m}`);
    const end = src.lastIndexOf('}');
    src = src.slice(0, end) + HELPER + src.slice(end);
    cfg.modResults.contents = src;
    return cfg;
  });
}

module.exports = (config) => withShareActivity(withShareManifest(config));
